from .inline_controls import request_text
from .providers import performance_directives
"""File-based review plans generated by an external Agent, never by Studio."""
import copy

from . import validation as v
from .core_v16 import uid
from .errors import require
from .questions import Questions
from .storage import atomic_write, digest, file_lock, read_json


def _path(core, plan_id):
    v.identifier(plan_id)
    return core.managed_path(f'.makesound/plans/{plan_id}.json')


def _hash(value):
    # Lifecycle metadata changes at confirmation; reviewed content must keep its original hash.
    return digest({key: item for key, item in value.items()
                   if key not in {'plan_hash', 'confirmation_hash', 'status'}})


def _validate_input(items, source_segments):
    require(isinstance(items, list) and len(items) == len(source_segments), 'plan_coverage',
            'The performance plan must cover every source sentence exactly once.')
    supplied = {}
    for item in items:
        v.shape(item, {'sentence_id', 'emotion', 'delivery_notes', 'filler_text', 'pause_after_ms', 'provider_directives', 'inline_controls'},
                {'sentence_id', 'emotion', 'delivery_notes', 'pause_after_ms'})
        v.identifier(item['sentence_id'])
        require(item['sentence_id'] not in supplied, 'plan_coverage', 'A source sentence may appear only once.')
        v.text(item['emotion'], 80)
        v.text(item['delivery_notes'], 1000)
        if item.get('filler_text') is not None:
            v.text(item['filler_text'], 120)
        require(type(item['pause_after_ms']) is int and 0 <= item['pause_after_ms'] <= 10000,
                'parameter_range', 'Pause must be an integer from 0 to 10000 milliseconds.')
        directives = item.get('provider_directives', {})
        require(isinstance(directives, dict) and set(directives) <= {'emotion'}, 'unsupported_directive',
                'This MiniMax adapter has no verified performance-directive mapping.')
        supplied[item['sentence_id']] = item
    expected = [segment['sentence_id'] for segment in source_segments]
    require(set(supplied) == set(expected), 'plan_coverage',
            'The performance plan must cover the unchanged source sentences.')
    return supplied


def propose(core, question_id, items):
    """Persist an external Agent's plan without claiming, freezing, or synthesizing."""
    v.identifier(question_id)
    question = Questions(core).read(question_id)
    require(question['status'] == 'answered' and question.get('answer'), 'not_answered',
            'Complete Studio settings before creating a performance plan.')
    handoff = read_json(core.managed_path(f'.makesound/handoffs/{question_id}.json'))
    require(handoff.get('question_id') == question_id and handoff.get('harness_session_id') == question['harness_session_id'],
            'session_mismatch', 'Trusted task handoff differs from the Studio Question.')
    source_segments = handoff.get('manifest', {}).get('segments')
    require(isinstance(source_segments, list) and source_segments, 'plan_coverage', 'Task manuscript is missing.')
    supplied = _validate_input(items, source_segments)
    preset = core.read()
    answer = question['answer']
    segments = []
    for source in source_segments:
        v.shape(source, {'paragraph_id', 'sentence_id', 'text', 'role_id', 'pause_ms', 'fake_duration_seconds'},
                {'paragraph_id', 'sentence_id', 'text', 'role_id'})
        role = source['role_id']
        resolved = answer['resolved'].get(role)
        require(resolved and resolved.get('status') == 'ready', 'missing_roles', 'Every manuscript role needs a resolved Studio voice.')
        voice_id = resolved['project_voice_id']
        voice = preset['voices'].get(voice_id)
        require(voice is not None or resolved.get('name'), 'voice_unavailable', 'The answered project voice no longer exists.')
        binding_snapshot = question.get('assignments', {}).get(role, {}).get('snapshot', {})
        snapshot_name = resolved.get('name') or (binding_snapshot.get('name') if binding_snapshot.get('project_voice_id') == voice_id
                         else voice['name'])
        plan_item = supplied[source['sentence_id']]
        request_text({'text': source['text'], 'source': resolved['source'], 'inline_controls': plan_item.get('inline_controls', [])})
        segments.append({
            'inline_controls': copy.deepcopy(plan_item.get('inline_controls', [])),
            'paragraph_id': source['paragraph_id'], 'sentence_id': source['sentence_id'], 'role_id': role, 'text': source['text'],
            'project_voice_id': voice_id,
            'voice_snapshot': {'project_voice_id': voice_id, 'name': snapshot_name,
                               'source': copy.deepcopy(resolved['source']),
                               'effective_settings': copy.deepcopy(resolved['effective_settings'])},
            'performance': {'emotion': plan_item['emotion'], 'delivery_notes': plan_item['delivery_notes'],
                            'filler_text': plan_item.get('filler_text'), 'pause_after_ms': plan_item['pause_after_ms']},
            'provider_directives': performance_directives(resolved['source'], plan_item.get('provider_directives')), 'directive_status': 'emotion_mapped' if plan_item.get('provider_directives') else 'not_mapped',
        })
    plan = {'schema_version': '1.8', 'plan_id': uid('plan_'), 'project_id': preset['project_id'],
            'question_id': question_id, 'job_id': question['job_id'], 'answer_id': answer['answer_id'],
            'manuscript_hash': digest(source_segments), 'status': 'pending_confirmation', 'segments': segments}
    plan['plan_hash'] = _hash(plan)
    v.no_secrets(plan)
    path = _path(core, plan['plan_id'])
    with file_lock(path.with_suffix('.lock')):
        require(not path.exists(), 'already_exists', 'A generated performance plan cannot be overwritten.')
        atomic_write(path, plan)
    return plan


def read(core, plan_id):
    plan = read_json(_path(core, plan_id))
    require(plan.get('schema_version') == '1.8' and plan.get('plan_id') == plan_id and plan.get('plan_hash') == _hash(plan),
            'plan_corrupt', 'Performance plan integrity check failed.')
    v.no_secrets(plan)
    return plan


def render(plan):
    require(plan.get('plan_hash') == _hash(plan), 'plan_corrupt', 'Performance plan integrity check failed.')
    lines = [f"表演计划 {plan['plan_id']}", f"任务：{plan['job_id']}", f"计划哈希：{plan['plan_hash']}", '']
    for index, item in enumerate(plan['segments'], 1):
        voice = item['voice_snapshot']
        settings = voice['effective_settings']
        unsupported = ('不支持', '未接入', '未核实', '不设置')
        def visible(value):
            return value and not any(marker in value for marker in unsupported)
        lines.extend([f'{index}. {item["text"]}',
                      f'   角色：{item["role_id"]}；声音：{voice["name"]} ({voice["project_voice_id"]})'])
        from .providers import capabilities, MINIMAX_DOCUMENTED_MODELS
        caps = capabilities(voice['source'])
        parameters = [f'{label} {settings.get(key, "默认")}' for key, label in (('speed', '语速'), ('pitch', '声调'))
                      if caps.get(key, {}).get('supported')]
        if parameters:
            lines.append('   参数：' + '；'.join(parameters))
        if voice['source']['provider'] == 'minimax' and voice['source']['model'] in MINIMAX_DOCUMENTED_MODELS:
            lines.append(f'   情绪参数：{item.get("provider_directives", {}).get("emotion", "自动")}')
        if visible(item['performance']['delivery_notes']):
            lines.append('   表演说明：' + item['performance']['delivery_notes'])
        if visible(item['performance'].get('filler_text')):
            lines.append('   原文语气词说明：' + item['performance']['filler_text'])
        lines.append(f'   段后停顿：{item["performance"]["pause_after_ms"]} ms')
        if item.get('inline_controls'):
            tagged = request_text({**item, 'source': voice['source']})
            lines.append(f'   请求文本（含确认的停顿/发声标签）：{tagged}')
    return '\n'.join(lines)


def confirm(core, plan_id, plan_hash):
    require(isinstance(plan_hash, str) and plan_hash, 'confirmation_required', 'Provide the reviewed plan hash.')
    path = _path(core, plan_id)
    with file_lock(path.with_suffix('.lock')):
        plan = read(core, plan_id)
        require(plan['status'] == 'pending_confirmation', 'plan_immutable', 'This performance plan was already confirmed.')
        require(plan['plan_hash'] == plan_hash, 'plan_changed', 'Plan content differs from the reviewed text.')
        plan['status'] = 'confirmed'
        plan['confirmation_hash'] = digest({'plan_id': plan_id, 'plan_hash': plan_hash, 'status': 'confirmed'})
        atomic_write(path, plan)
        return plan


def execution_segments(plan):
    require(plan.get('status') == 'confirmed' and plan.get('plan_hash') == _hash(plan), 'confirmation_required',
            'Confirm an unchanged performance plan before creating a Job.')
    return [{'paragraph_id': item['paragraph_id'], 'sentence_id': item['sentence_id'], 'role_id': item['role_id'],
             'text': item['text'], 'inline_controls': copy.deepcopy(item.get('inline_controls', [])), 'pause_ms': item['performance']['pause_after_ms'], **({'provider_directives': item['provider_directives']} if item.get('provider_directives') else {})} for item in plan['segments']]
